export function dispatchBrowserCommands(
  calls: BrowserCall[],          // parsed <call> {verb,noun,addinf,resfil}
  ctx: CommandContext,           // page-store, window-mgr, api, router
) {
  let responseFilter = "";       // set by DISPLAY_QUESTION
  for (const c of calls) {
    if (c.resfil && c.resfil !== responseFilter) continue;
    switch (c.verb) {
      case "SET_VISIBILITY": ctx.page.setVisible(c.noun, c.addinf==="1"); break;
      case "SET_DISABLED":   ctx.page.setDisabled(c.noun, c.addinf==="1"); break;
      case "SET_REQUIRED":   ctx.page.setRequired(c.noun, c.addinf==="1"); break;
      case "SET_TEXT":       ctx.page.setValue(c.noun, c.addinf); break;
      case "LOAD_COMBO":     ctx.page.loadOptions(c.noun, ctx.listItems); break;
      case "DISPLAY_QUESTION": responseFilter = await ctx.ui.confirm(c.addinf); break;
      case "NAVIGATE_CYCLING": return ctx.router.executeAction(...); // ends loop
      case "OPEN_MODAL":     ctx.windows.openModal(...); break;
      // ...~40 verbs total
    }
  }
}

