// design target: a focus utility keyed by matchcode
function focusControl(matchcode: string) {
  const el = document.querySelector<HTMLElement>(`[data-matchcode="${matchcode}"]`);
  if (!el) return;
  const tabId = el.closest('[data-tab-id]')?.getAttribute('data-tab-id');
  if (tabId) pageStore.setActiveTab(tabId);        // switch tab first
  if (!el.hasAttribute('disabled')) {
    el.focus();
    if (el instanceof HTMLInputElement) el.select();
  }
}

