// design target: derive the empty-option label from schema
function showZeroText(control: ControlSchema): string {
  const raw = (control.showzero ?? '').toString();
  const t = raw.toUpperCase();
  if (t === 'T') return 'NONE';
  if (t === 'F') return '';
  return t.startsWith('NOUCASE') ? raw.slice(8) : t; // NOUCASE = keep original case
}
